svg.script:
// Animación para el interruptor SPST
const spstSwitch = document.getElementById('spst-switch');
let spstState = false;

spstSwitch.addEventListener('click', function() {
    spstState = !spstState;
    if (spstState) {
        this.setAttribute('y1', '50');
        this.setAttribute('y2', '10');
    } else {
        this.setAttribute('y1', '10');
        this.setAttribute('y2', '50');
    }
});

// Animación para el pulsador NA
const pushButton = document.getElementById('pushbutton-na');

pushButton.addEventListener('mousedown', function() {
    this.style.strokeDasharray = '0,0';
});

pushButton.addEventListener('mouseup', function() {
    this.style.strokeDasharray = '5,3';
});

pushButton.addEventListener('mouseleave', function() {
    this.style.strokeDasharray = '5,3';
});

// Animación para el interruptor SPDT
const spdtSwitch1 = document.getElementById('spdt-switch-1');
const spdtSwitch2 = document.getElementById('spdt-switch-2');
let spdtState = false;

spdtSwitch1.addEventListener('click', function() {
    spdtState = !spdtState;
    if (spdtState) {
        spdtSwitch1.style.stroke = '#2ecc71';
        spdtSwitch1.style.strokeWidth = '3';
        spdtSwitch2.style.stroke = '#2c3e50';
        spdtSwitch2.style.strokeWidth = '2';
    } else {
        spdtSwitch1.style.stroke = '#2c3e50';
        spdtSwitch1.style.strokeWidth = '2';
        spdtSwitch2.style.stroke = '#2ecc71';
        spdtSwitch2.style.strokeWidth = '3';
    }
});

spdtSwitch2.addEventListener('click', function() {
    spdtState = !spdtState;
    if (spdtState) {
        spdtSwitch1.style.stroke = '#2ecc71';
        spdtSwitch1.style.strokeWidth = '3';
        spdtSwitch2.style.stroke = '#2c3e50';
        spdtSwitch2.style.strokeWidth = '2';
    } else {
        spdtSwitch1.style.stroke = '#2c3e50';
        spdtSwitch1.style.strokeWidth = '2';
        spdtSwitch2.style.stroke = '#2ecc71';
        spdtSwitch2.style.strokeWidth = '3';
    }
});

// Animación para el interruptor de mercurio
const mercuryDrop = document.getElementById('mercury-drop');
let mercuryState = false;

mercuryDrop.addEventListener('click', function() {
    mercuryState = !mercuryState;
    if (mercuryState) {
        this.setAttribute('cy', '35');
    } else {
        this.setAttribute('cy', '25');
    }
});
